def hook(ctx, nb):
    try:
        if ctx['action']['tool'] != 'click_action':
            return None
        val = ctx['action']['value_normalized']
    except Exception:
        return None
    if val != 'buy now':
        return None
    try:
        need = ctx['predicates']['required_options_unselected']
    except Exception:
        need = False
    if not need:
        return None
    try:
        clicks = ctx['state']['clickables']
    except Exception:
        clicks = []
    msg = 'Do not buy yet: a required product option is still unselected. Choose the visible option that matches the instruction, such as color, size, material, flavor, style, or length; if no matching option is available, use Back to Search.'
    for c in clicks:
        if c == 'buy now' or c == 'back to search' or c == '< prev' or c == 'next >' or c == 'description' or c == 'features' or c == 'reviews':
            continue
        msg = msg + ' [visible option: ' + str(c) + ']' + ' '
    return {'kind': 'block_and_prompt', 'message': msg}
